-- SafeEat 2.0: accent-safe names, real chains, trusted chain reviews.
-- Additive: the previous API image keeps working on this schema.

-- 1. One normalization rule for SQL and Rust (generated by crates/text-norm).
--    Folds accents in both cases before lower(), so it no longer depends on the
--    database collation ("ÁNGEL" used to become "ngel").
CREATE OR REPLACE FUNCTION restaurant_brand_name(value text) RETURNS text
LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE AS $$
SELECT regexp_replace(lower(replace(replace(replace(replace(replace(replace(replace(replace(translate(value,'áàâäãåāąÁÀÂÄÃÅĀĄéèêëēęěÉÈÊËĒĘĚíìîïīıÍÌÎÏĪİóòôöõøōőÓÒÔÖÕØŌŐúùûüūůűÚÙÛÜŪŮŰýÿÝŸñńňÑŃŇçćčÇĆČśšşŚŠŞźżžŹŻŽłŁřŘťŤďĎđĐğĞ','aaaaaaaaaaaaaaaaeeeeeeeeeeeeeeiiiiiiiiiiiioooooooooooooooouuuuuuuuuuuuuuyyyynnnnnnccccccsssssszzzzzzllrrttddddgg'),'ß','ss'),'ẞ','ss'),'æ','ae'),'Æ','ae'),'œ','oe'),'Œ','oe'),'þ','th'),'Þ','th')),'[^a-z0-9]','','g')
$$;
REINDEX INDEX restaurant_catalog_name_group_idx;
REINDEX INDEX community_restaurants_name_group_idx;

-- 2. Accent-insensitive search keys with trigram indexes.
ALTER TABLE restaurant_catalog ADD COLUMN search_name text
  GENERATED ALWAYS AS (restaurant_brand_name(name)) STORED;
CREATE INDEX restaurant_catalog_search_name_trgm ON restaurant_catalog USING gin(search_name gin_trgm_ops);
CREATE INDEX community_restaurants_search_name_trgm ON community_restaurants
  USING gin(restaurant_brand_name(name) gin_trgm_ops);

-- 3. Raw OSM brand identity, kept apart from the derived chain assignment so the
--    weekly refresh can recompute chains from scratch.
ALTER TABLE restaurant_catalog ADD COLUMN brand text;
ALTER TABLE restaurant_catalog ADD COLUMN brand_wikidata text;
UPDATE restaurant_catalog SET brand=chain_name,
  brand_wikidata=CASE WHEN chain_key ~ '^Q[0-9]+$' THEN chain_key END;

-- Generic words never define a chain by themselves.
CREATE TABLE restaurant_generic_names (alias text PRIMARY KEY);
INSERT INTO restaurant_generic_names(alias) VALUES
 ('restaurante'),('restaurant'),('bar'),('cafe'),('cafeteria'),('cerveceria'),('pizzeria'),
 ('taberna'),('meson'),('asador'),('bodega'),('pasteleria'),('panaderia'),('churreria'),
 ('heladeria'),('kebab'),('burger'),('sushi'),('tapas'),('casa'),('cocina'),('grill'),
 ('pub'),('tasca'),('marisqueria'),('creperia'),('braseria'),('sidreria'),('vinoteca'),
 ('chiringuito'),('kiosko'),('quiosco'),('horno'),('obrador'),('wok'),('bistro'),('gastrobar'),
 ('pollosasados'),('bocateria'),('hamburgueseria'),('comidachina'),('pizza'),('doner'),('frankfurt'),
 ('tiendadealimentacion'),('alimentacion'),('supermercado'),('autoservicio'),('minimarket'),
 ('fruteria'),('carniceria'),('cafebar'),('barrestaurante'),('restaurantebar'),('bocadilleria'),
 ('donerkebab'),('kebabhouse'),('pizzakebab');

-- Chains with their branch counts (rebuilt by refresh_restaurant_chains()).
CREATE TABLE restaurant_chains (
 key text PRIMARY KEY,
 name text NOT NULL,
 alias text NOT NULL,
 branch_count integer NOT NULL DEFAULT 0
);
CREATE INDEX restaurant_chains_alias_trgm ON restaurant_chains USING gin(alias gin_trgm_ops);

-- 4. Confirmations survive re-keying a chain or narrowing a chain review to its branch;
--    any change of content (support/status, note, revocation) still invalidates them.
CREATE OR REPLACE FUNCTION invalidate_review_confirmations() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF TG_OP='UPDATE'
   AND (to_jsonb(NEW) - ARRAY['chain_key','scope','revision']) = (to_jsonb(OLD) - ARRAY['chain_key','scope','revision'])
   AND (to_jsonb(NEW)->>'scope' IS NOT DISTINCT FROM to_jsonb(OLD)->>'scope' OR to_jsonb(NEW)->>'scope'='local') THEN
   RETURN NEW;
 END IF;
 DELETE FROM review_confirmations WHERE report_id=OLD.id;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 NEW.revision=gen_random_uuid();
 RETURN NEW;
END $$;

CREATE OR REPLACE FUNCTION refresh_restaurant_chains() RETURNS void LANGUAGE plpgsql AS $$
BEGIN
 -- A chain review applies to every branch, so a wrong branch is a safety problem while a
 -- missing one only shows "no information". Every rule below errs on the side of leaving out.
 --
 -- A brand tag only counts when the venue's own name carries the brand: bars tagged with
 -- their beer sponsor ("Mahou", "Estrella Galicia") are not branches of a chain.
 DELETE FROM restaurant_chain_aliases;
 -- a) Brands with exactly one explicit Wikidata identity.
 INSERT INTO restaurant_chain_aliases(alias,chain_key,chain_name)
 SELECT restaurant_brand_name(brand),min(brand_wikidata),mode() WITHIN GROUP (ORDER BY brand)
 FROM restaurant_catalog
 WHERE brand_wikidata ~ '^Q[0-9]+$' AND brand IS NOT NULL
   AND length(restaurant_brand_name(brand))>=3
   AND strpos(search_name,restaurant_brand_name(brand))>0
 GROUP BY restaurant_brand_name(brand) HAVING count(DISTINCT brand_wikidata)=1;
 -- b) Brands without Wikidata that at least five venues named after them share.
 INSERT INTO restaurant_chain_aliases(alias,chain_key,chain_name)
 SELECT restaurant_brand_name(brand),'brand:'||restaurant_brand_name(brand),mode() WITHIN GROUP (ORDER BY brand)
 FROM restaurant_catalog
 WHERE brand IS NOT NULL AND length(restaurant_brand_name(brand))>=4
   AND strpos(search_name,restaurant_brand_name(brand))>0
 GROUP BY restaurant_brand_name(brand) HAVING count(*)>=5
 ON CONFLICT(alias) DO NOTHING;
 DELETE FROM restaurant_chain_aliases a USING restaurant_generic_names g WHERE a.alias=g.alias;

 -- Recompute every assignment.
 UPDATE restaurant_catalog SET chain_key=NULL,chain_name=NULL WHERE chain_key IS NOT NULL;
 -- 1. Own Wikidata identity.
 UPDATE restaurant_catalog c SET chain_key=c.brand_wikidata,
   chain_name=COALESCE((SELECT a.chain_name FROM restaurant_chain_aliases a WHERE a.chain_key=c.brand_wikidata LIMIT 1),c.brand)
 WHERE c.brand_wikidata ~ '^Q[0-9]+$' AND length(restaurant_brand_name(c.brand))>=3
   AND strpos(c.search_name,restaurant_brand_name(c.brand))>0;
 -- 2. Brand tag of a known chain.
 UPDATE restaurant_catalog c SET chain_key=a.chain_key,chain_name=a.chain_name
 FROM restaurant_chain_aliases a
 WHERE c.chain_key IS NULL AND c.brand IS NOT NULL AND a.alias=restaurant_brand_name(c.brand)
   AND strpos(c.search_name,a.alias)>0;
 -- 3. Untagged venues named like an established chain: the longest leading run of words
 --    ("Burger King Gran Vía", "VIPS - Sol"). Only for chains with at least 20 tagged branches,
 --    and only when the name matches add at most 15% to them; otherwise the name is too
 --    common to identify a chain ("El Rincón de …", "Viena Capellanes" is not "Viena").
 WITH tagged AS (
   SELECT chain_key,count(*) AS n FROM restaurant_catalog
   WHERE chain_key IS NOT NULL GROUP BY chain_key HAVING count(*)>=20
 ), candidates AS (
   SELECT DISTINCT ON (c2.id) c2.id,a.chain_key,a.chain_name
   FROM restaurant_catalog c2
   CROSS JOIN LATERAL (
     SELECT restaurant_brand_name(array_to_string(s.w[1:n],' ')) AS k,n
     FROM (SELECT regexp_split_to_array(btrim(regexp_replace(c2.name,'[-–—·|()]',' ','g')),'\s+') AS w) s,
          generate_series(1,least(coalesce(array_length(s.w,1),0),6)) n
   ) p
   JOIN restaurant_chain_aliases a ON a.alias=p.k
   JOIN tagged t ON t.chain_key=a.chain_key
   WHERE c2.chain_key IS NULL AND length(p.k)>=4
   ORDER BY c2.id,p.n DESC
 ), accepted AS (
   SELECT m.chain_key FROM candidates m JOIN tagged t USING (chain_key)
   GROUP BY m.chain_key,t.n HAVING count(*)<=t.n*0.15
 )
 UPDATE restaurant_catalog c SET chain_key=m.chain_key,chain_name=m.chain_name
 FROM candidates m JOIN accepted USING (chain_key) WHERE c.id=m.id;

 DELETE FROM restaurant_chains;
 INSERT INTO restaurant_chains(key,name,alias,branch_count)
 SELECT chain_key,mode() WITHIN GROUP (ORDER BY chain_name),restaurant_brand_name(mode() WITHIN GROUP (ORDER BY chain_name)),count(*)
 FROM restaurant_catalog WHERE chain_key IS NOT NULL GROUP BY chain_key HAVING count(*)>=2;

 -- Chain reviews follow their branch's (new) chain identity; same-name reviews whose
 -- branch now belongs to a chain move to that chain.
 UPDATE restaurant_gluten_reports r SET chain_key=c.chain_key
 FROM restaurant_catalog c WHERE r.restaurant_id=c.id AND c.chain_key IS NOT NULL
   AND r.chain_key IS DISTINCT FROM c.chain_key AND r.scope='chain';
 -- Remaining same-name keys use the current normalization.
 UPDATE restaurant_gluten_reports r SET chain_key='name:'||restaurant_brand_name(COALESCE(c.name,cr.name))
 FROM restaurant_gluten_reports r2
 LEFT JOIN restaurant_catalog c ON c.id=r2.restaurant_id
 LEFT JOIN community_restaurants cr ON cr.id=r2.restaurant_id
 WHERE r.id=r2.id AND r.scope='chain' AND r.chain_key LIKE 'name:%'
   AND COALESCE(c.chain_key,'')='' AND COALESCE(c.name,cr.name) IS NOT NULL
   AND r.chain_key IS DISTINCT FROM 'name:'||restaurant_brand_name(COALESCE(c.name,cr.name));
END $$;

-- 5. Only trusted accounts (ADMIN / authorized_celiac) may mark whole chains.
--    Existing chain reviews from other accounts now apply to their own branch only.
WITH downgraded AS (
 UPDATE restaurant_gluten_reports r SET scope='local',chain_key=NULL
 WHERE r.scope='chain' AND NOT EXISTS(
   SELECT 1 FROM user_roles ur WHERE ur.user_id=r.user_id AND ur.role_code IN ('ADMIN','authorized_celiac'))
 RETURNING r.id,r.restaurant_id,r.user_id)
INSERT INTO admin_audit_log(actor_id,action,target_id,details)
SELECT NULL,'chain_review_downgraded',id::text,
  jsonb_build_object('restaurantId',restaurant_id,'userId',user_id,
    'reason','Solo las cuentas de confianza pueden marcar cadenas completas.')
FROM downgraded;

SELECT refresh_restaurant_chains();
